	c = mix(c, c * 0.55, wxLine(vn(w * 0.8 + 3.0), 0.01) * (0.4 + heave) * mid);
	c = mix(c, vec3(0.2, 0.2, 0.19), wxSpots(wl, 0.33, 0.018, 0.12) * fine);
